     static class Range implements Comparable<Range> {
         int from;
         int to;

         public Range(int from, int to) {
             this.from = from;
             this.to = to;

             if (to <= 0 || to < from) {
                 this.to = this.from = -1;
             }
         }

         boolean isInvalid() {
             return from == -1 || to == -1;
         }

         boolean intersects(Range other) {
             if (isInvalid() || other.isInvalid()) {
                 return false;
             }

             return this.from <= other.to && other.from <= this.to;
         }

         @Override
         public int compareTo(Range o) {
             int res = from - o.from;
             if (res != 0) {
                 return res;
             }

             return to - o.to;
         }
     }

     static class MaxFlow {
         int source;
         int sink;

         Set<Edge>[] forward;
         Set<Edge>[] backward;

         Vertex[] path;

         @SuppressWarnings("unchecked")
         public MaxFlow(int n) {
             source = 0;
             sink = n - 1;

             forward = new Set[n];
             backward = new Set[n];
             for (int i = 0; i < n; ++i) {
                 forward[i] = new HashSet<>();
                 backward[i] = new HashSet<>();
             }

             path = new Vertex[n];
         }


         public void addEdge(int v, int u, int c) {
             Edge edge = new Edge(v, u, c);
             forward[v].add(edge);
             backward[u].add(edge);
         }

         public int flow() {
             compute();

             int flow = 0;
             for (Edge edge : forward[source]) {
                 flow += edge.flow;
             }

             return flow;
         }

         private void compute() {
             while (findAugmentingPath()) {
                 processPath();
             }
         }

         private boolean findAugmentingPath() {
             Arrays.fill(path, null);

             path[source] = new Vertex(-1, false, null);

             return findAugmentingPath(source);
         }

         private boolean findAugmentingPath(int v) {
             if (v == sink) {
                 return true;
             }

             for (Edge edge : forward[v]) {
                 if (path[edge.to] == null && edge.capacity > edge.flow) {
                     path[edge.to] = new Vertex(v, true, edge);
                     if (findAugmentingPath(edge.to)) {
                         return true;
                     }
                 }
             }

             for (Edge edge : backward[v]) {
                 if (path[edge.from] == null && edge.flow > 0) {
                     path[edge.from] = new Vertex(v, false, edge);
                     if (findAugmentingPath(edge.from)) {
                         return true;
                     }
                 }
             }

             path[v] = null;

             return false;
         }

         private void processPath() {
             int delta = findDelta();
             adjustFlow(delta);
         }

         private int findDelta() {
             int v = sink;
             int delta = Integer.MAX_VALUE;
             while (v != source) {
                 Vertex vertex = path[v];
                 Edge edge = vertex.edge;
                 int t;
                 if (vertex.isForward) {
                     t = edge.capacity - edge.flow;
                 } else {
                     t = edge.flow;
                 }
                 if (t < delta) {
                     delta = t;
                 }

                 v = vertex.start;
             }

             return delta;
         }

         private void adjustFlow(int delta) {
             int v = sink;
             while (v != source) {
                 Vertex vertex = path[v];
                 Edge edge = vertex.edge;
                 if (vertex.isForward) {
                     edge.flow += delta;
                 } else {
                     edge.flow -= delta;
                 }

                 v = vertex.start;
             }
         }

         static class Vertex {
             int start;
             boolean isForward;
             Edge edge;

             Vertex(int start, boolean isForward, Edge edge) {
                 this.start = start;
                 this.isForward = isForward;
                 this.edge = edge;
             }
         }

         static class Edge {
             int from;
             int to;
             int capacity;
             int flow;

             Edge(int from, int to, int capacity) {
                 this.from = from;
                 this.to = to;
                 this.capacity = capacity;
                 flow = 0;
             }
         }
     }

