     x = new long[n];
     y = new long[n];
     z = new long[n];
     for (int i = 0; i < n; i++) {
       x[i] = in.nextInt();
       y[i] = in.nextInt();
       z[i] = in.nextInt();
       in.nextInt();
       in.nextInt();
       in.nextInt();
     }
     double[][] dist = new double[n][n];
     for (int i = 0; i < n; i++) {
       for (int j = 0; j < n; j++) {
         dist[i][j] = 
             Math.sqrt(
                 (x[i]-x[j])*(x[i]-x[j])+
                 (y[i]-y[j])*(y[i]-y[j])+
                 (z[i]-z[j])*(z[i]-z[j]));
       }
     }

     double lo = 0, hi = 10000;
     for (int iter = 0; iter < 100; iter++) {
       double mid = (lo+hi) / 2;
       int[] queue = new int[n];
       boolean[] vis = new boolean[n];
       int front = 0, back = 0;
       queue[back++] = 0;
       vis[0] = true;
       while (front < back) {
         int cur = queue[front++];
         for (int next = 0; next < n; next++) {
           if (!vis[next] & dist[cur][next] <= mid) {
             vis[next] = true;
             queue[back++] = next;
           }
         }
       }
       if (vis[1]) {
         hi = mid;
       } else {
         lo = mid;
       }
     }

     out.printf("%.6f\n", lo);
   }

