    private void f(ArrayList<Integer> l)
    {

        if (valid(l))
            max = Math.max(max, l.size());
        if(!validInTheMiddle(l))
            return;


        for (int i = 0; i < n; i++)
            if (!l.contains(i))
            {
                ArrayList<Integer> newList = new ArrayList<>();
                newList.addAll(l);
                newList.add(i);
                f(newList);
            }

