    {
        int countUp = 0;
        int ans = 0;
        for (int i = 0; i < n; i++) 
            if (arr[i] == 0)
                continue;
            else
            {

                if (i > countUp)
                {
                    int required = i - countUp;
                    countUp += required;
                    ans += required;
                }


                countUp += arr[i];
            }

        return ans;
    }

