package exo3;











 public class Exo extends Base {

    public static void main(String[] argv) {






        configSmall(0, false);





        try {
            int testCaseCount = input().nextInt();
            for (int i = 1; i <= testCaseCount; ++i) {
                info("CASE #" + i + " ###################################################");





                output().println("Case #" + i + ": " + solveTestCase());



            }
        }
        catch (Exception e) {
            e.printStackTrace(System.err);
        }
        finally {
            done();
        }
    }





    private static double solveTestCase() {

        int N = input().nextInt();
        int K = input().nextInt();
        double U = input().nextDouble();

        double[] p = new double[N];
        for (int i = 0; i < N; ++i) {
            p[i] = input().nextDouble();
        }

        Arrays.sort(p);

        while (U > 1e-10) {
            int index = findFirstBlocker(N, p);
            double maxIncr = index == N ? 1d : p[index];
            double incr = Math.min(maxIncr - p[0], U / index);

            for (int i = 0; i < index; ++i) {
                p[i] += incr;
            }
            U -= incr * index;
        }

        return product(N, p);
    }

    private static int findFirstBlocker(int N, double[] p) {
        for (int i = 1; i < N; ++i) {
            if (p[i] > p[0]) {
                return i;
            }
        }
        return N;
    }

    private static double product(int N, double[] p) {
        double res = 1;
        for (int i = 0; i < N; ++i) {
            res *= p[i];
        }
        return res;
    }

 }









