    public static long solveA(int[] list) {
        long ret = 0;
        for(int i = 0; i < list.length-1; i++) {
            ret += Math.max(-list[i+1] + list[i], 0);
        }
        return ret;
    }

    public static long solveB(int[] list) {
        long ret = 0;
        int maxRate = 0;
        for(int i = 0; i < list.length-1; i++) {
            maxRate = Math.max(maxRate, -list[i+1] + list[i]);
        }
        for(int i = 0; i < list.length-1; i++) {
            ret += Math.min(list[i], maxRate);
        }
        return ret;
    }

