public class B_1A_GCJ2015 {

     public static long MOD = 1000000007;
     static int[] X = {0, 1};
     static int[] Y = {1, 0};
     static int[][][] dp;

     public static void main(String[] args) throws FileNotFoundException {
         PrintWriter out = new PrintWriter(new FileOutputStream(new File(
                 "output.txt")));

         Scanner in = new Scanner();
         int T = in.nextInt();

         for (int t = 0; t < T; t++) {
             int b = in.nextInt();
             long n = in.nextInt();
             long[] data = new long[b];
             for (int i = 0; i < b; i++) {
                 data[i] = in.nextInt();
             }
             long start = 0;
             long end = 100000000000000000L;
             long min = end;
             while (start <= end) {
                 long mid = (start + end) >> 1;

                 long total = 0;
                 for (int i = 0; i < b; i++) {
                     total += 1 + mid / data[i];
                 }

                 if (total >= n) {
                     if (min > end) {
                         min = mid;
                     }
                     end = mid - 1;
                 } else {
                     start = mid + 1;
                 }
             }
             long last = 0;
             PriorityQueue<Node> q = new PriorityQueue();
             for (int i = 0; i < b; i++) {
                 last += 1 + (min - 1) / data[i];
                 long nxt = (min - 1) / data[i];
                 nxt = (nxt + 1) * data[i];
                 q.add(new Node(i, nxt));
             }
             n -= last;

             int result = 0;
             for(int i = 0; i < n; i++){
                 Node node = q.poll();
                 result = node.index + 1;
                 q.add(new Node(node.index , node.t + data[node.index]));
             }
             out.println("Case #" + (t + 1) + ": " + result);
         }
         out.close();
     }

     static class Node implements Comparable<Node> {

         int index;
         long t;

         Node(int index, long t) {
             this.index = index;
             this.t = t;
         }

         @Override
         public int compareTo(Node o) {
             if (t != o.t) {
                 return Long.compare(t, o.t);
             } else {
                 return index - o.index;
             }
         }
     }

     public static int[] KMP(String val) {
         int i = 0;
         int j = -1;
         int[] result = new int[val.length() + 1];
         result[0] = -1;
         while (i < val.length()) {
             while (j >= 0 && val.charAt(j) != val.charAt(i)) {
                 j = result[j];
             }
             j++;
             i++;
             result[i] = j;
         }
         return result;

     }

     public static boolean nextPer(int[] data) {
         int i = data.length - 1;
         while (i > 0 && data[i] < data[i - 1]) {
             i--;
         }
         if (i == 0) {
             return false;
         }
         int j = data.length - 1;
         while (data[j] < data[i - 1]) {
             j--;
         }
         int temp = data[i - 1];
         data[i - 1] = data[j];
         data[j] = temp;
         Arrays.sort(data, i, data.length);
         return true;
     }

     public static int digit(long n) {
         int result = 0;
         while (n > 0) {
             n /= 10;
             result++;
         }
         return result;
     }

     public static double dist(long a, long b, long x, long y) {
         double val = (b - a) * (b - a) + (x - y) * (x - y);
         val = Math.sqrt(val);
         double other = x * x + a * a;
         other = Math.sqrt(other);
         return val + other;



     }

     public static class Point implements Comparable<Point> {

         int x, y;

         public Point(int start, int end) {
             this.x = start;
             this.y = end;
         }

         @Override
         public int hashCode() {
             int hash = 5;
             hash = 47 * hash + this.x;
             hash = 47 * hash + this.y;
             return hash;
         }

         @Override
         public boolean equals(Object obj) {
             if (obj == null) {
                 return false;
             }
             if (getClass() != obj.getClass()) {
                 return false;
             }
             final Point other = (Point) obj;
             if (this.x != other.x) {
                 return false;
             }
             if (this.y != other.y) {
                 return false;
             }
             return true;
         }

         @Override
         public int compareTo(Point o) {
             return x - o.x;
         }
     }

     public static class FT {

         long[] data;

         FT(int n) {
             data = new long[n];
         }

         public void update(int index, long value) {
             while (index < data.length) {
                 data[index] += value;
                 index += (index & (-index));
             }
         }

         public long get(int index) {
             long result = 0;
             while (index > 0) {
                 result += data[index];
                 index -= (index & (-index));
             }
             return result;

         }
     }

     public static long gcd(long a, long b) {
         if (b == 0) {
             return a;
         }
         return gcd(b, a % b);
     }

     public static long pow(long a, long b) {
         if (b == 0) {
             return 1;
         }
         if (b == 1) {
             return a;
         }
         long val = pow(a, b / 2);
         if (b % 2 == 0) {
             return val * val % MOD;
         } else {
             return val * (val * a % MOD) % MOD;


         }
     }

     static class Scanner {

         BufferedReader br;
         StringTokenizer st;

         public Scanner() throws FileNotFoundException {


              br = new BufferedReader(new InputStreamReader(new FileInputStream(new File("B-small-attempt0.in"))));
         }

         public String next() {

             while (st == null || !st.hasMoreTokens()) {
                 try {
                     st = new StringTokenizer(br.readLine());
                 } catch (Exception e) {
                     throw new RuntimeException();
                 }
             }
             return st.nextToken();
         }

         public long nextLong() {
             return Long.parseLong(next());
         }

         public int nextInt() {
             return Integer.parseInt(next());
         }

         public double nextDouble() {
             return Double.parseDouble(next());
         }

         public String nextLine() {
             st = null;
             try {
                 return br.readLine();
             } catch (Exception e) {
                 throw new RuntimeException();
             }
         }

         public boolean endLine() {
             try {
                 String next = br.readLine();
                 while (next != null && next.trim().isEmpty()) {
