             if (N == 0)
                 ans = "INSOMNIA";
             else
                 ans = f(N) + "";

             System.out.printf("Case #%d: ", n + 1);
             System.out.println(ans);
         }
     }

     static long f(long n)
     {
         Set<Long> digits = new HashSet<Long>();
         long nMult = 0;
         while (digits.size() < 10)
         {
             nMult += n;
             long nCopy = nMult;
             while (nCopy > 0)
             {
                 digits.add(nCopy % 10);
                 nCopy /= 10;
             }
         }
         return nMult;
     }
 }
