    public void solve() throws IOException {
        char[] c = in.next().toCharArray();
        int ans = 0;
        while (true) {
            boolean isMinus = false;
            for (char cc : c) {
                if (cc == '-') {
                    isMinus = true;
                }
            }
            if (!isMinus) {
                break;
            }
            ans++;
            if (c[0] == '+') {
                int p = 0;
                while (p < c.length && c[p] == '+') {
                    c[p++] = '-';
                }
            } else {
                int p = c.length;
                while (p > 0 && c[p - 1] == '+') {
                    p--;
                }
                int l = 0, r = p - 1;
                while (l < r) {
                    char t = c[l];
                    c[l] = c[r];
                    c[r] = t;
                    l++;
                    r--;
                }
                for (int i = 0; i < p; i++) {
                    c[i] = (c[i] == '+') ? '-' : '+';
                }
            }
        }
        out.println(ans);
    }

