public class A {
    FastScanner in;
    PrintWriter out;

    int sol(String s) {
        int n = s.length();
        int[][] dp = new int[n + 1][n + 1];
        for (int len = 2; len <= n; len++) {
            for (int fr = 0; fr + len <= n; fr++) {
                for (int l1 = 2; l1 <= len; l1++) {
                    dp[fr][len] = Math.max(dp[fr][len], dp[fr][l1]
                            + dp[fr + l1][len - l1]);
                }
                dp[fr][len] = Math.max(
                        dp[fr][len],
                        dp[fr + 1][len - 2]
                                + (s.charAt(fr) == s.charAt(fr + len - 1) ? 10
                                        : 5));
            }
        }
        return dp[0][n];
    }

