     FastScanner in;
     PrintWriter out;

     void solve() {
         int tc = in.nextInt();
         for (int t = 0; t < tc; t++) {
             out.print("Case #" + (t + 1) + ": ");
             int n = in.nextInt();
             int p = in.nextInt();

             int[] ri = new int[n];
             for (int i = 0; i < n; i++) {
                 ri[i] = in.nextInt();
             }
             int[][] sizes = new int[n][p];
             for (int i = 0; i < n; i++) {
                 for (int j = 0; j < p; j++) {
                     sizes[i][j] = in.nextInt();
                 }
                 Arrays.sort(sizes[i]);
             }
             int[] it = new int[n];
             int result = 0;
             int count = 1;
             while (true) {
                 boolean ok = true;
                 for (int i = 0; i < n; i++) {
                     while (it[i] < p && sizes[i][it[i]] * 10L < 9L * count * ri[i]) {
                         it[i]++;
                     }
                     if (it[i] == p) {
                         ok = false;
                     }
                 }
                 if (!ok) {
                     break;
                 }
                 for (int i = 0; i < n; i++) {
                     if (sizes[i][it[i]] * 10L > 11L * count * ri[i]) {
                         ok = false;
                     }
                 }
                 if (!ok) {
                     count++;
                     continue;
                 }
                 result++;
                 for (int i = 0; i < n; i++) {
                     it[i]++;
                 }
             }
             out.println(result);
             System.err.println((t + 1) + "/" + tc + " done");
         }
     }

