    private List<Integer> solution;

    private void readCase(final Scanner in) {
        pieces = new ArrayList<>();
        N = in.nextInt();
        for (int i = 0; i < 2 * N - 1; i++) {
            List<Integer> piece = new ArrayList<Integer>();
            for (int j = 0; j < N; j++) {
                piece.add(in.nextInt());
            }
            pieces.add(piece);
        }
    }

    private void solveCase() {
        Map<Integer, Integer> heights = new HashMap<>();
        pieces.forEach(piece -> piece.forEach(height -> {
            if (heights.containsKey(height)) {
                int oldCount = heights.get(height);
                heights.put(height, oldCount + 1);
            } else {
                heights.put(height, 1);
            }
        }));

        List<Integer> missing = new ArrayList<Integer>();
        heights.entrySet().forEach(entry -> {
            if (entry.getValue() % 2 == 1) {
                missing.add(entry.getKey());
            }
        });

        Collections.sort(missing);
        solution = missing;
    }

    private void printOutput(final PrintStream out) {
        solution.forEach(x -> out.print(x + " "));
    }
 }
