 class TaskA {
     static String dir = ".^>v<";

     public void solve(int testNumber, InputReader in, PrintWriter out) {
         out.print("Case #" + testNumber + ": ");
         int R = in.nextInt();
         int C = in.nextInt();
         int[][] map = new int[R][C];
         for (int i = 0; i < R; i++) {
             String s = in.next();
             s = s.replace("&gt;", ">");
             s = s.replace("&lt;", "<");
             for (int j = 0; j < C; j++) {
                 if (s.charAt(j) == '.') continue;
                 map[i][j] = dir.indexOf(s.charAt(j));
             }
         }
         for (int i = 0; i < R; i++) {
             for (int j = 0; j < C; j++) {
                 if (map[i][j] == 0) continue;
                 int l = j-1;
                 while (l >= 0 && map[i][l] == 0) l--;
                 int r = j+1;
                 while (r < C && map[i][r] == 0) r++;
                 int u = i-1;
                 while (u >= 0 && map[u][j] == 0) u--;
                 int b = i+1;
                 while (b < R && map[b][j] == 0) b++;
                 if (l == -1 && r == C && u == -1 && b == R) {
                     out.println("IMPOSSIBLE");
                     return;
                 }
             }
         }
         int ans = 0;
         for (int i = 0; i < R; i++) {
             int l = 0;
             while (l < C && map[i][l] == 0) l++;
             if (l < C && map[i][l] == 4) ans++;
             int r = C-1;
             while (r >= 0 && map[i][r] == 0) r--;
             if (r >= 0 && map[i][r] == 2) ans++;
         }
         for (int i = 0; i < C; i++) {
             int t = 0;
             while (t < R && map[t][i] == 0) t++;
             if (t < R && map[t][i] == 1) ans++;
             int b = R-1;
             while (b >= 0 && map[b][i] == 0) b--;
             if (b >= 0 && map[b][i] == 3) ans++;
         }

         out.println(ans);
     }
 }

