public class ProblemA1a {
     BufferedReader rd;

     ProblemA1a() throws IOException {
         rd = new BufferedReader(new InputStreamReader(System.in));
         compute();
     }

     private void compute() throws IOException {
         int n = pint();
         for(int i=0;i<n;i++) {
             out("Case #" + (i + 1) + ": " + solve());
         }
     }

     private String solve() throws IOException {
         String[] h = split(rd.readLine());
         boolean[] d = toBooleanArray(h[0].toCharArray());
         int k = pint(h[1]);
         int res = solve(d, k);
         return res == -1 ? "IMPOSSIBLE" : Integer.toString(res);
     }

     private int solve(boolean[] d, int k) {
         int n = d.length;
         int i = 0;
         int flipCount = 0;
         while(i<=n-k) {
             if(!d[i]) {
                 flipCount++;
                 for(int j=0;j<k;j++) {
                     int p = i+j;
                     d[p] = !d[p];
                 }
             }
             i++;
         }
         while(i < n) {
             if(!d[i]) {
                 return -1;
             }
             i++;
         }
         return flipCount;
     }

     private boolean[] toBooleanArray(char[] c) {
         int n = c.length;
         boolean[] res = new boolean[n];
         for(int i=0;i<n;i++) {
             res[i] = c[i] == '+';
         }
         return res;
     }

     private int pint() throws IOException {
         return pint(rd.readLine());
     }

     private int pint(String s) {
         return Integer.parseInt(s);
     }

     public String[] split(String s) {
         if(s == null) {
             return new String[0];
         }
         int n = s.length();
