package con2017.con2017R1C;















 public class A {

   static final String islarge = "-large";
   private static final String[] packages = A.class.getPackage().getName().split("\\.");
   private static final String fileLoc = "src/" + packages[0] + "/" + packages[1] + "/files/";
   private static final String fileName = fileLoc + A.class.getSimpleName().toLowerCase();
   private static final String inputFileName = fileName + ".in";
   private static final String outputFileName = fileName + ".out";
   private static InputReader in;
   private static OutputWriter out;

   static class Pair {
     private final int r, h;
     private final double sf1, sf2;

     public Pair(int radius, int height) {
       this.r = radius;
       this.h = height;
       sf1 = 1D * this.r * this.r;
       sf2 = 2D * this.r * this.h;
     }
   }


   private void solve() {
     int N = in.readInt(), K = in.readInt();
     Pair[] ps = new Pair[N];
     for (int i = 0; i < N; i++) {
       ps[i] = new Pair(in.readInt(), in.readInt());
     }
     Arrays.sort(ps, (Pair a, Pair b) -> {
       if (a.sf2 == b.sf2) {
         return a.sf1 > b.sf1 ? -1 : 1;
       }
       return a.sf2 > b.sf2 ? -1 : 1;
     });
     double tot = 0;
     Pair maxr = ps[0];
     for (int i = 0; i < K - 1; i++) {
       tot += ps[i].sf2;
       if (maxr.r < ps[i].r) {
         maxr = ps[i];
       }
     }
     double max = 0D;
     for (int j = K - 1; j < N; j++) {
       double ex = ps[j].sf2;
       if (ps[j].r > maxr.r) {
         ex += ps[j].sf1;
       } else {
         ex += maxr.sf1;
       }
       max = Math.max(max, ex);
     }
     out.printLine(Math.PI * (tot + max));
   }


   private static void printCase(int t) {
     out.print("Case #" + t + ": ");
   }

   public static void main(String[] args) throws IOException {
     long start = System.currentTimeMillis();
     System.out.println("Contest: " + packages[1] + " problem: " + A.class.getSimpleName());
     System.out.println("Solving " + (fileName.endsWith(islarge) ? "LARGE" : "SMALL") + " dataset");
     System.out.println("------------------------------");
     Locale.setDefault(Locale.US);
     try (InputReader closeIn = new InputReader(new FileInputStream(inputFileName));
         OutputWriter closeOut = new OutputWriter(new FileOutputStream(outputFileName))) {
       in = closeIn;
       out = closeOut;
       int tests = in.readInt();
       for (int t = 1; t <= tests; t++) {
         printCase(t);
         new A().solve();
         System.out.println("Case #" + t + ": solved");
       }
     } finally {
       System.out.println("------------------------------");
       long stop = System.currentTimeMillis();
       System.out.println("Time: " + (stop - start) + " ms");
     }
   }


   static class InputReader implements AutoCloseable {
     private InputStream stream;
     private byte[] buf = new byte[1024];
     private int curChar;
     private int numChars;

     public InputReader(InputStream stream) {
       this.stream = stream;
     }

     public int read() {
       if (numChars == -1)
         throw new InputMismatchException();
       if (curChar >= numChars) {
         curChar = 0;
         try {
           numChars = stream.read(buf);
         } catch (IOException e) {
           throw new InputMismatchException();
         }
         if (numChars <= 0)
           return -1;
       }
       return buf[curChar++];
     }

     public String readLine() {
       int c = read();
       while (isSpaceChar(c))
         c = read();
       StringBuilder res = new StringBuilder();
       do {
         res.appendCodePoint(c);
         c = read();
       } while (!isEndOfLine(c));
       return res.toString();
     }

     public String readString() {
       int c = read();
       while (isSpaceChar(c))
         c = read();
       StringBuilder res = new StringBuilder();
       do {
         res.appendCodePoint(c);
         c = read();
       } while (!isSpaceChar(c));
       return res.toString();
     }

     public long readLong() {
       int c = read();
       while (isSpaceChar(c))
         c = read();
       int sgn = 1;
       if (c == '-') {
         sgn = -1;
         c = read();
       }
       long res = 0;
       do {
         if (c < '0' || c > '9')
           throw new InputMismatchException();
         res *= 10;
         res += c - '0';
         c = read();
       } while (!isSpaceChar(c));
       return res * sgn;
     }

     public int readInt() {
       int c = read();
       while (isSpaceChar(c))
         c = read();
       int sgn = 1;
       if (c == '-') {
         sgn = -1;
         c = read();
       }
       int res = 0;
       do {
         if (c < '0' || c > '9')
           throw new InputMismatchException();
         res *= 10;
         res += c - '0';
         c = read();
       } while (!isSpaceChar(c));
       return res * sgn;
     }

     public boolean isSpaceChar(int c) {
       return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
     }

     public boolean isEndOfLine(int c) {
       return c == '\n' || c == '\r' || c == -1;
     }

     public void close() throws IOException {
       stream.close();
     }
   }

   static class OutputWriter implements AutoCloseable {
     private final PrintWriter writer;

     public OutputWriter(OutputStream outputStream) {
       writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
     }

     public OutputWriter(Writer writer) {
       this.writer = new PrintWriter(writer);
     }

     public void print(Object... objects) {
       for (int i = 0; i < objects.length; i++) {
         if (i != 0)
           writer.print(' ');
         writer.print(objects[i]);
       }
     }

     public void printLine(Object... objects) {
       print(objects);
       writer.println();
     }

     public void close() {
       writer.close();
     }
   }
 }
