package R2;






 import static java.util.Arrays.*;

 public class D {

    static
    class Config {
        public static final boolean DISP_PROGRESS = true;
        public static final boolean DISP_ELASPED_TIME = true;
        public static final boolean STDIO = false;

        public static final String BASE_DIR = "data\\R2\\D";
        public static final String IN_FILE = "D-small-attempt3.in";
        public static final String OUT_FILE = IN_FILE + "_out.txt";
        public static final int MAX_THREAD = 3;
    }



    static
    class ParallelSolver implements Runnable {
        private static final int mod = (int)1e9+7;

        int w, h;
        public void readInput(final IOFast io) throws IOException {
            h = io.nextInt();
            w = io.nextInt();
        }

        @Override
        public void run() {
            cell = new int[h][w];
            for(int i = 0; i < h; i++) Arrays.fill(cell[i], -1);
            ans = 0;
            dfs(0, 0);
            out.println(ans);
        }

        int[][] cell;
        long ans;
        void dfs(int x, int y) {
            if(x >= w) {
                for(int j = 0; j < w; j++) {
                    if(!possible(j, y) || !possible(j, y-1)) {
                        return;
                    }
                }
                dfs(0, y + 1);
                return;
            }

            if(y >= h) {
                for(int i = 0; i < h; i++) {
                    for(int j = 0; j < w; j++) {
                        if(cell[i][j] == -1) throw new RuntimeException();
                        if(!possible(j, i)) {
                            return;
                        }
                    }
                }
                ans++;
                return;
            }

            for(int i = 0; i <= 4; i++) {
                cell[y][x] = i;
                if(!possible(x-1, y) || !possible(x, y-1) || !possible(x, y)
                         || !possible(x, y+1) || !possible(x+1, y)) {
                    continue;
                }
                dfs(x + 1, y);
            }
            cell[y][x] = -1;
        }

        int[] dx = new int[]{1,0,-1,0,};
        int[] dy = new int[]{0,-1,0,1,};
        boolean possible(int x, int y) {
            if(x < 0 || y < 0 || y >= h) return true;
            if(x >= w) x -= w;
            if(cell[y][x] == -1) return true;
            int same = 0;
            int empty = 0;
            for(int i = 0; i < 4; i++) {
                int xx = x + dx[i];
                int yy = y + dy[i];
                if(xx < 0) xx += w;
                if(xx >= w) xx -= w;
                if(yy < 0 || yy >= h) continue;

                if(cell[y][x] == cell[yy][xx]) {
                    same++;
                }
                else if(cell[yy][xx] == -1) {
                    empty++;
                }
            }

            return same <= cell[y][x] && same + empty >= cell[y][x];
        }



