         for (int i = 1; i <= testCount; i++)
             solver.solve(i, in, out);
         out.close();
     }

     static class TaskB {
         private static final int MAX_CNT = 3 * 1000 * 1000;

         public void solve(int testNumber, InputReader in, OutputWriter out) {
             out.printFormat("Case #%d: ", testNumber);
             int n = in.readInt();
             int p = in.readInt();
             long[] req = IOUtils.readLongArray(in, n);
             long[][] a = IOUtils.readLongTable(in, n, p);
             for (long[] row : a) {
                 Arrays.sort(row);
             }
             boolean[][] used = new boolean[n][p];
             long ans = 0;
             long[] low = new long[n];
             long[] high = new long[n];
             for (int cnt = 1; cnt <= MAX_CNT; cnt++) {
                 for (int i = 0; i < n; i++) {
                     long x = req[i] * cnt;
                     low[i] = (long) (x * 0.9 - 5);
                     high[i] = (long) (x * 1.1 + 5);
                     if (low[i] < 1) {
                         low[i] = 1;
                     }
                     while (low[i] * 10 < x * 9 && low[i] < x) { 
                         low[i]++;
                     }
                     while (high[i] * 10 > x * 11 && high[i] > x) { 
                         high[i]--;
                     }
                     if (low[i] > high[i]) {
                         throw new AssertionError();
                     }
                 }

                 boolean someoneIsOutOfRange = false;
                 for (int i = 0; i < n; i++) {
                     if (a[i][p - 1] < low[i]) {
                         someoneIsOutOfRange = true;
                     }
                 }
                 if (someoneIsOutOfRange) {
                     break;
                 }

                 int min = Integer.MAX_VALUE;
                 for (int i = 0; i < n; i++) {
                     int valid = 0;
                     for (int j = 0; j < p; j++) {
                         if (!used[i][j] && low[i] <= a[i][j] && a[i][j] <= high[i]) {
                             valid++;
                         }
                     }
                     min = Math.min(min, valid);
                 }
                 if (min == 0) {
                     continue;
                 }

                 for (int i = 0; i < n; i++) {
                     int rem = min;
                     for (int j = 0; j < p; j++) {
                         if (!used[i][j] && low[i] <= a[i][j] && a[i][j] <= high[i]) {
                             used[i][j] = true;
                             rem--;
                             if (rem == 0) {
                                 break;
                             }
                         }
                     }
                 }






                 ans += min;
             }
             System.err.println("Finished test case " + testNumber);
             System.err.flush();
             out.printLine(ans);
         }

     }

     static class IOUtils {
         public static long[] readLongArray(InputReader in, int size) {
             long[] array = new long[size];
             for (int i = 0; i < size; i++) {
                 array[i] = in.readLong();
             }
             return array;
         }

         public static long[][] readLongTable(InputReader in, int rowCount, int columnCount) {
             long[][] table = new long[rowCount][];
             for (int i = 0; i < rowCount; i++) {
                 table[i] = readLongArray(in, columnCount);
             }
             return table;
         }

     }

