 static class DisjointSet {
    int[] p, r;

    DisjointSet(int s) {
        p = new int[s];
        r = new int[s];
        for (int i = 0; i < s; i++)
            p[i] = i;

    }

    void union(int x, int y) {
        int a = find(x);
        int b = find(y);
        if (a == b)
            return;
        if (r[a] == r[b])
            r[p[b] = a]++;
        else
            p[a] = p[b] = r[a] < r[b] ? b : a;
    }

    int find(int x) {
        return p[x] = p[x] == x ? x : find(p[x]);
    }

 }

 }
