     private static boolean check(int r, int c, char[][] field, Set<Cell> cells) {
         Set<Cell> cntr = new HashSet<Cell>();
         boolean imp = false;
         for (int i = 0; i < r; i++) {
             for (int j = 0; j < c; j++) {
                 if (field[i][j] == '-') {
                     int cr = j - 1;
                     while (cr >= 0) {
                         if (field[i][cr] == '.') {
                             cntr.add(new Cell(i,cr));
                         }
                         if (field[i][cr] == '#') {
                             break;
                         }
                         if (field[i][cr] == '-' || field[i][cr] == '|') {
                             imp = true;
                             break;
                         }
                         cr--;
                     }
                     cr = j + 1;
                     while (cr < c) {
                         if (field[i][cr] == '.') {
                             cntr.add(new Cell(i,cr));
                         }
                         if (field[i][cr] == '#') {
                             break;
                         }
                         if (field[i][cr] == '-' || field[i][cr] == '|') {
                             imp = true;
                             break;
                         }
                         cr++;
                     }
                 }
                 if (field[i][j] == '|') {
                     int cr = i - 1;
                     while (cr >= 0) {
                         if (field[cr][j] == '.') {
                             cntr.add(new Cell(cr,j));
                         }
                         if (field[cr][j] == '#') {
                             break;
                         }
                         if (field[cr][j] == '-' || field[cr][j] == '|') {
                             imp = true;
                             break;
                         }
                         cr--;
                     }
                     cr = i + 1;
                     while (cr < r) {
                         if (field[cr][j] == '.') {
                             cntr.add(new Cell(cr,j));
                         }
                         if (field[cr][j] == '#') {
