             if (n==2 && m==1) {
                 String res = "Case #" + ti + ": POSSIBLE\n01\n00";
                 printWriter.write(res + "\n");
                 System.out.println(res);
                 continue;
             }
             if (n==2 && m>1) {
                 String res = "Case #" + ti + ": IMPOSSIBLE";
                 printWriter.write(res + "\n");
                 System.out.println(res);
                 continue;
             }
             int nv = 1 + ((n - 1) * (n - 2));
             int cnt = 1 << nv;
             System.err.println(cnt);
             int cntt = 0;
             boolean ok = false;
             int [] rx = new int[nv];
             int [] cx = new int[nv];
             int cidx = 0;
             for (int i=0;i<n-1;i++) {
                 for (int j=1;j<=n-1;j++) {
                     if (i!=j) {
                         rx[cidx] = i;
                         cx[cidx] = j;
                         cidx++;
                     }
                 }
             }
             inner:
             for (int i = 0; i < cnt; i++) {
                 Map<Integer, Set<Integer>> map = new HashMap<Integer, Set<Integer>>();
                 Map<Integer, Integer> income = new HashMap<Integer, Integer>();
                 int k = i;
                 int kx = 0;
                 while (k > 0) {
                     if (k % 2 == 1) {
                         int v = rx[kx];
                         int v2 = cx[kx];
