     private boolean ok(int r, int c, int r1, int c1, char[][] a) {
         for (int i = min(r,r1); i <= max(r,r1); i++) {
             for (int j = min(c,c1); j <= max(c,c1); j++) {
                 if (i==r&&j==c) continue;
                 if (a[i][j]!='?') {
                     return false;
                 }
             }
         }
         return true;
     }

     private int idx(int r, int c, int C) {
