             for (int c = 0; c < a[r].length; c++) {
                 if (a[r][c] != '?') {                    
                     hasR[r]=true;
                     hasC[c]=true;
                 }
             }
         }
         boolean useR = true;
         boolean useC = true;
         for (int i = 0; i < hasR.length; i++) {
             if (!hasR[i]) {
                 useR=false;
             }
         }
         for (int i = 0; i < hasC.length; i++) {
             if (!hasC[i]) {
                 useC=false;
             }
         }
         if (useR) {
             for (int r = 0; r < R; r++) {
                 char ch = '?';
                 for (int c = 0; c < C; c++) {
                     if (a[r][c]!='?') {
                         if (ch == '?') {
                             for (int i = 0; i < c; i++) {
                                 a[r][i]=a[r][c];
                             }
                         }
                         ch = a[r][c];
                     }
                     a[r][c] = ch;
                 }
             }
             return a;
         } else if (useC) {
             for (int c = 0; c < C; c++) {
                 char ch = '?';
                 for (int r = 0; r < R; r++) {
                     if (a[r][c]!='?') {
                         if (ch == '?') {
                             for (int i = 0; i < r; i++) {
                                 a[i][c]=a[r][c];
                             }
                         }
                         ch = a[r][c];
                     }
                     a[r][c] = ch;
                 }
             }            
             return a;
         }        
         return null;
     }

