     static class TaskAlphabetCake {
         public void solve(int testNumber, InputReader in, OutputWriter out) {
             out.printLine("Case #" + testNumber + ":");

             int rowCount = in.readInt();
             int columnCount = in.readInt();
             char[][] table = IOUtils.readTable(in, rowCount, columnCount);

             for (int i = 0; i < rowCount; i++) {
                 for (int j = 1; j < columnCount; j++) {
                     if (table[i][j - 1] != '?' && table[i][j] == '?') {
                         table[i][j] = table[i][j - 1];
                     }
                 }

                 for (int j = columnCount - 2; j >= 0; j--) {
                     if (table[i][j + 1] != '?' && table[i][j] == '?') {
                         table[i][j] = table[i][j + 1];
                     }
                 }
             }

             while (haveQuestion(table)) {
                 for (int i = 1; i < rowCount; i++) {
                     for (int j = 0; j < columnCount; j++) {
                         if (table[i - 1][j] == '?') {
                             table[i - 1][j] = table[i][j];
                         }
                     }
                 }

                 for (int i = 0; i < rowCount - 1; i++) {
                     for (int j = 0; j < columnCount; j++) {
                         if (table[i + 1][j] == '?') {
                             table[i + 1][j] = table[i][j];
                         }
                     }
                 }
             }

             for (int i = 0; i < rowCount; i++) {
                 out.printLine(String.valueOf(table[i]));
             }
         }

         private boolean haveQuestion(char[][] table) {
             for (int i = 0; i < table.length; i++) {
                 for (char c : table[i]) {
                     if (c == '?') {
                         return true;
                     }
                 }
             }
             return false;
         }

     }

     static class InputReader {
         private InputStream stream;
         private byte[] buf = new byte[1024];
         private int curChar;
         private int numChars;
         private InputReader.SpaceCharFilter filter;

         public InputReader(InputStream stream) {
             this.stream = stream;
         }

         public int read() {
             if (numChars == -1) {
                 throw new InputMismatchException();
             }
             if (curChar >= numChars) {
                 curChar = 0;
                 try {
                     numChars = stream.read(buf);
                 } catch (IOException e) {
                     throw new InputMismatchException();
                 }
                 if (numChars <= 0) {
                     return -1;
                 }
             }
             return buf[curChar++];
         }

         public int readInt() {
             int c = read();
             while (isSpaceChar(c)) {
                 c = read();
             }
             int sgn = 1;
             if (c == '-') {
                 sgn = -1;
                 c = read();
             }
             int res = 0;
             do {
                 if (c < '0' || c > '9') {
                     throw new InputMismatchException();
                 }
                 res *= 10;
                 res += c - '0';
                 c = read();
             } while (!isSpaceChar(c));
             return res * sgn;
         }

         public String readString() {
             int c = read();
             while (isSpaceChar(c)) {
                 c = read();
             }
             StringBuilder res = new StringBuilder();
             do {
                 if (Character.isValidCodePoint(c)) {
                     res.appendCodePoint(c);
                 }
                 c = read();
             } while (!isSpaceChar(c));
             return res.toString();
         }

         public boolean isSpaceChar(int c) {
             if (filter != null) {
                 return filter.isSpaceChar(c);
             }
             return isWhitespace(c);
         }

         public static boolean isWhitespace(int c) {
             return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
         }

         public char readCharacter() {
             int c = read();
             while (isSpaceChar(c)) {
                 c = read();
             }
             return (char) c;
         }

         public String next() {
             return readString();
         }

         public interface SpaceCharFilter {
             public boolean isSpaceChar(int ch);

         }

     }

     static class OutputWriter {
         private final PrintWriter writer;

         public OutputWriter(OutputStream outputStream) {
             writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
         }

         public OutputWriter(Writer writer) {
             this.writer = new PrintWriter(writer);
         }

         public void print(Object... objects) {
             for (int i = 0; i < objects.length; i++) {
                 if (i != 0) {
                     writer.print(' ');
                 }
                 writer.print(objects[i]);
             }
         }

         public void printLine(Object... objects) {
             print(objects);
             writer.println();
         }

         public void close() {
             writer.close();
         }

     }

     static class IOUtils {
         public static char[] readCharArray(InputReader in, int size) {
             char[] array = new char[size];
             for (int i = 0; i < size; i++) {
                 array[i] = in.readCharacter();
             }
             return array;
         }

         public static char[][] readTable(InputReader in, int rowCount, int columnCount) {
             char[][] table = new char[rowCount][];
             for (int i = 0; i < rowCount; i++) {
                 table[i] = readCharArray(in, columnCount);
             }
             return table;
         }

     }
 }

