 class TaskC {
     private int sign = 1;

     public void solve(int testNumber, InputReader in, OutputWriter out) {
         out.print("Case #" + testNumber + ": ");
         int count = in.readInt();
         int times = in.readInt();
         String s = in.readString();
         StringBuilder builder = new StringBuilder();
         for (int i = 0; i < times; i++) {
             builder.append(s);
         }
         s = builder.toString();

         count = s.length();
         int[] letterI = new int[count];
         int[] letterK = new int[count];

         char prev = '?';
         sign = 1;
         for (int i = 0; i < count; i++) {
             if (prev == '?') {
                 prev = s.charAt(i);
             } else {
                 prev = combine(prev, s.charAt(i));
             }
             letterI[i] = sign * (prev == 'i' ? 1 : 0);
         }

         prev = '?';
         sign = 1;
         for (int i = count - 1; i >= 0; i--) {
             if (prev == '?') {
                 prev = s.charAt(i);
             } else {
                 prev = combine(s.charAt(i), prev);
             }
             letterK[i] = sign * (prev == 'k' ? 1 : 0);
         }

         boolean haveAnswer = false;
         for (int i = 0; i < count; i++) {
             if (letterI[i] > 0) {
                 prev = '?';
                 sign = 1;
                 for (int j = i + 1; j < count; j++) {
                     if (prev == '?') {
                         prev = s.charAt(j);
                     } else {
                         prev = combine(prev, s.charAt(j));
                     }
                     if (prev == 'j' && sign > 0 && j + 1 < count && letterK[j + 1] > 0) {
                         haveAnswer = true;
                         break;
                     }
                 }
                 if (haveAnswer) {
                     break;
                 }
             }
         }

         out.printLine(haveAnswer ? "YES" : "NO");
     }

     private char combine(char x, char y) {
         if (x == 'i') {
             if (y == 'i') {
                 sign *= -1;
                 return '?';
             }
             if (y == 'j') {
                 return 'k';
             }
             if (y == 'k') {
                 sign *= -1;
                 return 'j';
             }
         } else if (x == 'j') {
             if (y == 'i') {
                 sign *= -1;
                 return 'k';
             }
             if (y == 'j') {
                 sign *= -1;
                 return '?';
             }
             if (y == 'k') {
                 return 'i';
             }
         } else {
             if (y == 'i') {
                 return 'j';
             }
             if (y == 'j') {
                 sign *= -1;
                 return 'i';
             }
             if (y == 'k') {
                 sign *= -1;
                 return '?';
             }
         }
         return '?';
     }
 }

