        int n = MAX / L < X ? MAX : (int) (L * X);
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            int j = (int) (i % L);
            switch (ss.charAt(j)) {
            case '1':
                a[i] = 1;
                break;
            case 'i':
                a[i] = 2;
                break;
            case 'j':
                a[i] = 3;
                break;
            case 'k':
                a[i] = 4;
                break;
            }
        }
        int s = 1;
        for (int i = 0; i < L; i++) {
            s = mul(s, a[i]);
        }
        if (pow(s, X) != -1) {
            out.write("NO");
            return;
        }
        s = 1;
        int step = 0;
        for (int i = 0; i < n; i++) {
            s = mul(s, a[i]);
            if (step == 0) {
                if (s == 2) {
                    step++;
                    s = 1;
                }
            } else {
                if (s == 3) {
                    step++;
                    break;
                }
            }
        }
        if (step == 2) {
            out.write("YES");
        } else {
            out.write("NO");
        }
    }

    int[][] mul = new int[][] { new int[] { 1, 2, 3, 4 },
            new int[] { 2, -1, 4, -3 }, new int[] { 3, -4, -1, 2 },
            new int[] { 4, 3, -2, -1 } };

    int mul(int x, int y) {
        int ans = 1;
        if (x < 0) {
            ans = -ans;
            x = -x;
        }
        if (y < 0) {
            ans = -ans;
            y = -y;
        }
        return ans * mul[x - 1][y - 1];
    }

    int pow(int x, long k) {
        int res = 1;
        while (k > 0) {
            if (k % 2 == 1)
                res = mul(res, x);
            x = mul(x, x);
            k /= 2;
        }
        return res;
    }

