     public void solve() throws Exception {
         for (int i = 0; i < MAX; i++) {
             arr[i].clear();
         }

         N = iread();
         d = new Dice[N];
         for (int i = 0; i < N; i++) {
             d[i] = new Dice();
             d[i].num = i;
             for (int j = 0; j < 6; j++) {
                 int c = iread();
                 for (int z = 0; z < j; z++) {
                     if (d[i].x[z] == c) {
                         c = -1;
                         break;
                     }
                 }
                 d[i].x[j] = c;
                 if (c >= 0) {
                     arr[c].add(d[i]);
                 }
             }
         }



         int ans = 0;

         left = 1;
         for (int cur = 1; cur < MAX; cur++) {
             sol[cur] = null;

             ID++;
             Dice d = khun(cur);
             int nxt = cur;
             if (d != null) {
                 nxt = d.best;
             }
             while (left <= nxt) {
                 if (sol[left] != null) {
                     sol[left].cur = 0;
                     sol[left] = null;
                 }
                 left++;
             }

             sol[cur] = d;

             int x = cur;
             while (d != null) {
                 int y = d.cur;
                 d.cur = x;
                 sol[x] = d;
                 d = d.next;
                 x = y;
             }
             ans = Math.max(ans, cur - left + 1);
         }
         fout.write(ans + "");
     }

     Dice khun(int x) {
         if (was[x] == ID) {
             return bb[x];
         }

         ArrayList<Dice> cand = arr[x];

         was[x] = ID;
         bb[x] = null;
         Dice best = null;

         for (int i = 0; i < cand.size(); i++) {
             Dice a = cand.get(i);

             if (a.cur == 0) {
                 a.best = 0;
                 a.id = ID;
                 a.next = null;
                 return a;
             }
         }

         for (int i = 0; i < cand.size(); i++) {
             Dice a = cand.get(i);

             if (a.id != ID) {
                 a.id = ID;
                 a.best = a.cur;
                 a.next = khun(a.cur);
                 if (a.next != null) {
                     if (a.next.best < a.cur) {
                         a.best = a.next.best;
                     } else {
                         a.next = null;
                     }
                 } else {
                     a.best = a.cur;
                 }

                 if (best == null || a.best < best.best) {
                     best = a;
                     if (best.best == 0) break;
                 }
             }
         }

         bb[x] = best;
         return best;
     }

     int N;
     Dice[] d;
     Dice[] sol;
     int left;
     int ID = 0;
     int[] was;
     Dice[] bb;

