     static class IntArrayQueue implements IntQueue {
         private int[] data;
         private int from;
         private int to;

         public IntArrayQueue(int capacity) {
             data = new int[Integer.highestOneBit(capacity) << 1];
         }

         public IntArrayQueue() {
             this(3);
         }

         public IntArrayQueue(int[] array) {
             this(array.length);
             to = array.length;
             System.arraycopy(array, 0, data, 0, to);
         }

         public IntArrayQueue(IntStream s) {
             addAll(s);
         }

         public IntArrayQueue(IntCollection c) {
             this(c.size());
             addAll(c);
         }

         public int size() {
             return (to - from) & (data.length - 1);
         }

         public void add(int v) {
             ensureCapacity(size() + 1);
             data[to++] = v;
             to &= data.length - 1;
         }

         public int poll() {
             if (from == to) {
                 throw new NoSuchElementException();
             }
             int result = data[from++];
             from &= data.length - 1;
             return result;
         }

         public IntIterator intIterator() {
             return new IntIterator() {
                 private int at = from;

                 public int value() {
                     if (at == to) {
                         throw new NoSuchElementException();
                     }
                     return data[at];
                 }

                 public boolean advance() {
                     if (!isValid()) {
                         throw new NoSuchElementException();
                     }
                     at++;
                     at &= data.length - 1;
                     return isValid();
                 }

                 public boolean isValid() {
                     return at != to;
                 }

                 public void remove() {
                     throw new UnsupportedOperationException();
                 }
             };
         }

         private void ensureCapacity(int capacity) {
             if (data.length <= capacity) {
                 int[] newData = new int[Integer.highestOneBit(capacity) << 1];
                 if (from <= to) {
                     System.arraycopy(data, from, newData, 0, size());
                 } else {
                     System.arraycopy(data, from, newData, 0, data.length - from);
                     System.arraycopy(data, 0, newData, data.length - from, to);
                 }
                 to = size();
                 from = 0;
                 data = newData;
             }
         }

     }

     static abstract class CharAbstractStream implements CharStream {

         public String toString() {
             StringBuilder builder = new StringBuilder();
             boolean first = true;
             for (CharIterator it = charIterator(); it.isValid(); it.advance()) {
                 if (first) {
                     first = false;
                 } else {
                     builder.append(' ');
                 }
                 builder.append(it.value());
             }
             return builder.toString();
         }


         public boolean equals(Object o) {
             if (!(o instanceof CharStream)) {
                 return false;
             }
             CharStream c = (CharStream) o;
             CharIterator it = charIterator();
             CharIterator jt = c.charIterator();
             while (it.isValid() && jt.isValid()) {
                 if (it.value() != jt.value()) {
                     return false;
                 }
                 it.advance();
                 jt.advance();
             }
             return !it.isValid() && !jt.isValid();
         }


         public int hashCode() {
             int result = 0;
             for (CharIterator it = charIterator(); it.isValid(); it.advance()) {
                 result *= 31;
                 result += it.value();
             }
             return result;
         }

     }

     static interface CharList extends CharReversableCollection {
         public abstract char get(int index);

         public abstract void addAt(int index, char value);

         public abstract void removeAt(int index);

         default public CharIterator charIterator() {
             return new CharIterator() {
                 private int at;
                 private boolean removed;

                 public char value() {
                     if (removed) {
                         throw new IllegalStateException();
                     }
                     return get(at);
                 }

                 public boolean advance() {
                     at++;
                     removed = false;
                     return isValid();
                 }

                 public boolean isValid() {
                     return !removed && at < size();
                 }

                 public void remove() {
                     removeAt(at);
                     at--;
                     removed = true;
                 }
             };
         }


         default public void add(char value) {
             addAt(size(), value);
         }

     }

     static class InputReader {
         private InputStream stream;
         private byte[] buf = new byte[1024];
         private int curChar;
         private int numChars;
         private InputReader.SpaceCharFilter filter;

         public InputReader(InputStream stream) {
             this.stream = stream;
         }

         public int read() {
             if (numChars == -1) {
                 throw new InputMismatchException();
             }
             if (curChar >= numChars) {
                 curChar = 0;
                 try {
                     numChars = stream.read(buf);
                 } catch (IOException e) {
                     throw new InputMismatchException();
                 }
                 if (numChars <= 0) {
                     return -1;
                 }
             }
             return buf[curChar++];
         }

         public int readInt() {
             int c = read();
             while (isSpaceChar(c)) {
                 c = read();
             }
             int sgn = 1;
             if (c == '-') {
                 sgn = -1;
                 c = read();
             }
             int res = 0;
             do {
                 if (c < '0' || c > '9') {
                     throw new InputMismatchException();
                 }
                 res *= 10;
                 res += c - '0';
                 c = read();
             } while (!isSpaceChar(c));
             return res * sgn;
         }

         public boolean isSpaceChar(int c) {
             if (filter != null) {
                 return filter.isSpaceChar(c);
             }
             return isWhitespace(c);
         }

         public static boolean isWhitespace(int c) {
             return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
         }

         public char readCharacter() {
             int c = read();
             while (isSpaceChar(c)) {
                 c = read();
             }
             return (char) c;
         }

         public interface SpaceCharFilter {
             public boolean isSpaceChar(int ch);

         }

     }

