                 private IntIterator it = intIterator();

                 public boolean hasNext() {
                     return it.isValid();
                 }

                 public Integer next() {
                     int result = it.value();
                     it.advance();
                     return result;
                 }
             };
         }

         default public int compareTo(IntStream c) {
             IntIterator it = intIterator();
             IntIterator jt = c.intIterator();
             while (it.isValid() && jt.isValid()) {
                 int i = it.value();
                 int j = jt.value();
                 if (i < j) {
                     return -1;
                 } else if (i > j) {
                     return 1;
                 }
                 it.advance();
                 jt.advance();
             }
             if (it.isValid()) {
                 return 1;
             }
             if (jt.isValid()) {
                 return -1;
             }
             return 0;
         }

