                     for (int i = 0; i < s.length; i++) {
                         if (s[i] == '-') {
                             if (i > s.length - k) {
                                 answer = -1;
                                 return;
                             }
                             answer++;
                             for (int j = i; j < i + k; j++) {
                                 if (s[j] == '-') {
