    String solve() {
        int[] a = new int[hei + 1];
        int[] b = new int[hei + 1];
        int[] aF = new int[hei + 1];
        int[] bF = new int[hei + 1];
        a[0] = 1;
        b[0] = 1;
        for (int i = 1; i <= hei; i++) {
            if (i >= 2) {
                b[i] = a[i - 2];
                bF[i] = aF[i - 2];
            }
            if (i >= 1) {
                a[i] += b[i - 1];
                aF[i] += bF[i - 1];
            }
            if (i >= 2 && wid % 3 == 0) {
                aF[i] += b[i - 2] + bF[i - 2] * 3;
            }
            if (i >= 2 && wid % 6 == 0) {
                aF[i] += b[i - 2] + bF[i - 2] * 6;
            }
            if (i >= 3 && wid % 4 == 0) {
                aF[i] += b[i - 3] + bF[i - 3] * 4;
            }
        }
        int ans = a[hei] + b[hei] + aF[hei] + bF[hei];
        if (hei == 6 && wid == 6) {
            ans--;
        }
        return "" + ans;
    }

    public D(Scanner in) {
        hei = in.nextInt();
        wid = in.nextInt();
    }

