    String solve() {
        boolean[][][] out = new boolean[2][2 * n - 1][2 * n - 1];
        int[][] orig = new int[n][n];
        int[][] set = new int[n][n];
        for (int i = 0; i < m; i++) {
            int type = types[i];
            int x = xs[i];
            int y = ys[i];
            orig[x][y] = type;
            if ((type & 1) != 0) {
                out[0][x][y] = true;
            }
            if ((type & 2) != 0) {
                out[1][x + y][x - y + n - 1] = true;
            }
        }
        for (int t = 0; t < 2; t++) {
            e = new boolean[2 * n - 1][2 * n - 1];
            for (int x = 0; x < n; x++) {
                for (int y = 0; y < n; y++) {
                    if (t == 0) {
                        e[x][y] = true;
                    } else {
                        e[x + y][x - y + n - 1] = true;
                    }
                }
            }
            boolean[] outI = new boolean[e.length];
            boolean[] outJ = new boolean[e.length];
            for (int i = 0; i < e.length; i++) {
                for (int j = 0; j < e.length; j++) {
                    if (out[t][i][j]) {
                        outI[i] = true;
                        outJ[j] = true;
                    }
                }               
            }
            for (int i = 0; i < e.length; i++) {
                for (int j = 0; j < e.length; j++) {
                    if (outI[i] || outJ[j]) {
                        e[i][j] = false;
                    }
                }
            }
            matching();
            for (int j = 0; j < e.length; j++) {
                int i = left[j];
                if (i == -1) {
                    continue;
                }
                if (t == 0) {
                    set[i][j] |= 1;
                } else {
                    System.out.println(i + " " + j);
                    set[(i + (j + 1 - n)) / 2][(i - (j + 1 - n)) / 2] |= 2;
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        int score = 0, added = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int v = orig[i][j] | set[i][j];
                score += Integer.bitCount(v);
                if (set[i][j] == 0) {
                    continue;
                }
                sb.append("\n" + SIGNS.charAt(v) + " " + (i + 1) + " " + (j + 1));
                added++;
            }
        }
        return score + " " + added + sb.toString();
    }

    public D(Scanner in) {
        n = in.nextInt();
        m = in.nextInt();
        types = new int[m];
        xs = new int[m];
        ys = new int[m];
        for (int i = 0; i < m; i++) {
            types[i] = SIGNS.indexOf(in.next().charAt(0));
