        int ans = 0;
        for (int i = 0; i < e.length; i++) {
            Arrays.fill(mark, false);
            if (dfs(i)) {
                ans++;
            }
        }
        return ans;
    }

    boolean dfs(int i) {
        if (mark[i]) {
            return false;
        }
        mark[i] = true;
        for (int j = 0; j < e[i].length; j++) {
            if (!e[i][j]) {
                continue;
            }
            if (left[j] == -1 || dfs(left[j])) {
                left[j] = i;
                return true;
            }
        }
        return false;
    }

